 const home=el('section');home.id='ownerWelcomeGuide';home.append(el('h3',"第一次使用：依这个顺序完成"),el('p',"平台首次设置 → 创建个体 → 填写并保存草稿 → 预览与批准 → 生活设置 → 亲自确认出生 → 阅读活动与成果"));const read=el('button',"阅读完整操作导引");read.onclick=()=>navigate('help');home.append(read);pageMap.home.prepend(home);
 const guide=el('section');guide.id='ownerNextGuide';guide.setAttribute('aria-label',"目前个体的下一步");const title=el('h3'),body=el('p'),next=el('button');next.className='primary';guide.append(title,body,next);ui.notice.after(guide);let action='identity';
